module multi_8bit
(
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);
    integer i;

    always @(*) begin
        product = 16'b0; 

        for (i = 0; i < 8; i = i + 1) begin
            if (B[i]) begin
                product = product + (A << i); 
            end
        end
    end

endmodule

module parallel2serial
(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [1:0] cnt;
    reg [3:0] data;
    reg valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b00;
            data <= 4'b0000;
            valid <= 1'b0;
        end else begin
            if (cnt == 2'b11) begin
                data <= d;
                cnt <= 2'b00;
                valid <= 1'b1;
            end else begin
                cnt <= cnt + 1;
                valid <= 1'b0;

                data <= {data[2:0], data[3]};
            end
        end
    end

    assign dout = data[3];
    assign valid_out = valid;
endmodule

module freq_div
(
    input CLK_in,
    input RST,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1
);

reg [3:0] cnt_10;
reg [6:0] cnt_100;

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        CLK_50 <= 1'b0;
    end else begin
        CLK_50 <= ~CLK_50;
    end
end

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        CLK_10 <= 1'b0;
        cnt_10 <= 4'b0000;
    end else begin
        if (cnt_10 == 4'd9) begin
            CLK_10 <= ~CLK_10;
            cnt_10 <= 4'b0000;
        end else begin
            cnt_10 <= cnt_10 + 1;
        end
    end
end

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        CLK_1 <= 1'b0;
        cnt_100 <= 7'b0000000;
    end else begin
        if (cnt_100 == 7'd99) begin
            CLK_1 <= ~CLK_1;
            cnt_100 <= 7'b0000000;
        end else begin
            cnt_100 <= cnt_100 + 1;
        end
    end
end

endmodule

module serial2parallel
(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output dout_parallel,
    output dout_valid
);

reg [7:0] dout_parallel_reg;
reg dout_valid_reg;
reg [3:0] cnt;

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        dout_parallel_reg <= 8'b0;
        dout_valid_reg <= 1'b0;
        cnt <= 4'b0;
    end
    begin
        if (din_valid)
        begin
            dout_parallel_reg[cnt] <= din_serial;
            cnt <= cnt + 1'b1;
            if (cnt == 4'd7)
            begin
                dout_valid_reg <= 1'b1;
            end
            begin
                dout_valid_reg <= 1'b0;
            end
        end
        begin
            cnt <= 4'b0;
            dout_valid_reg <= 1'b0;
        end
    end
end

assign dout_parallel = dout_parallel_reg;
assign dout_valid = dout_valid_reg;

endmodule

module fsm
(
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

localparam s0 = 3'b000;
localparam s1 = 3'b001;
localparam s2 = 3'b010;
localparam s3 = 3'b011;
localparam s4 = 3'b100;
localparam s5 = 3'b101;

reg [2:0] ST_cr, ST_nr;

always @(*) begin
    case(ST_cr)
        s0: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s0;
        end

        s1: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s2;
        end

        s2: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s3;
        end

        s3: begin
            if(IN) ST_nr = s4;
            else   ST_nr = s0;
        end

        s4: begin
            if(IN) ST_nr = s5;
            else   ST_nr = s2;
        end

        s5: begin
            if(IN) ST_nr = s1;
            else   ST_nr = s2;
        end

        default: ST_nr = s0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if(RST) ST_cr <= s0;
    else     ST_cr <= ST_nr;
end

always @(*) begin
    if(RST) MATCH = 1'b0;
    else if(ST_cr == s4 && IN == 1'b1) MATCH = 1'b1;
    else MATCH = 1'b0;
end

endmodule

module div_16bit
(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

always @(*) begin
    if (B == 0) begin
        result = 0;
        odd = A;
    end else begin
        result = A / B;
        odd = A % B;
    end
end

endmodule

module adder_16bit
(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);

wire [7:0] sum1, sum2, sum3, sum4;
wire c1, c2, c3, c4;

assign {c1, sum1} = a[7:0] + b[7:0] + Cin;
assign {c2, sum2} = a[15:8] + b[15:8] + c1;
assign {c3, sum3} = a[23:16] + b[23:16] + c2;
assign {Co, sum4} = a[31:24] + b[31:24] + c3;

assign y = {sum4, sum3, sum2, sum1};
endmodule

module counter_12
(
    input rst_n,
    input clk,
    input valid_count,
    output reg [3:0] out
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            out <= 4'b0000;
        else if (valid_count) begin
            if (out == 4'd11) out <= 4'b0000;
            else              out <= out + 1;
        end
    end
endmodule

module multi_16bit
(
    input clk,
    input rst_n,
    input start,
    input ain,
    input bin,
    output yout,
    output done
);

reg [15:0] areg, breg;
reg [31:0] yout_r;
reg [4:0] i;
reg done_r;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n)
        i <= 5'd0;
    else if (start && i < 5'd17)
        i <= i + 1;
    else if (!start)
        i <= 5'd0;
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n)
        done_r <= 1'b0;
    else if (i == 5'd16)
        done_r <= 1'b1;
    else if (i == 5'd17)
        done_r <= 1'b0;
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        areg <= 16'd0;
        breg <= 16'd0;
        yout_r <= 32'd0;
    end else if (start) begin
        if (i == 5'd0) begin
            areg <= ain;
            breg <= bin;
        end else if (i > 5'd0 && i < 5'd17) begin
            if (areg[i-1])
                yout_r <= yout_r + (breg << (i-1));
        end
    end
end

assign yout = yout_r;
assign done = done_r;
endmodule

module edge_detect
(
    input clk,
    input rst_n,
    input a,
    output rise,
    output down
);

reg a_sync;
reg rise_reg, down_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_sync <= 1'b0;
        rise_reg <= 1'b0;
        down_reg <= 1'b0;
    end else begin
        a_sync <= a;
        if (a && !a_sync) rise_reg <= 1'b1; else rise_reg <= 1'b0;

        if (!a && a_sync) down_reg <= 1'b1; else down_reg <= 1'b0;
    end
end

assign rise = rise_reg;
assign down = down_reg;

endmodule

