module adder_pipe_64bit
(
    input clk,
    input rst_n,
    input i_en,
    input [63:0] adda,
    input [63:0] addb,
    output [64:0] result,
    output o_en
);

reg [63:0] reg_adda, reg_addb;
reg [64:0] reg_result;
reg reg_o_en;

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        reg_adda <= 64'b0;
        reg_addb <= 64'b0;
        reg_result <= 65'b0;
        reg_o_en <= 1'b0;
    end
    else if (i_en)
    begin
        reg_adda <= adda;
        reg_addb <= addb;
        reg_result <= {1'b0, reg_adda} + {1'b0, reg_addb};
        reg_o_en <= 1'b1;
    end
        reg_o_en <= 1'b0;
end

assign result = reg_result;
assign o_en = reg_o_en;

endmodule

module accu
(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [9:0] accum_data;
reg valid_accum;

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        accum_data <= 0;
        valid_accum <= 0;
    end
    else if (valid_in)
    begin
        accum_data <= accum_data + {data_in, 2'b0};
        if (accum_data[9:4] != 0) valid_accum <= 1; else valid_accum <= 0;
    end
end

assign data_out = accum_data;
assign valid_out = valid_accum;

endmodule

module synchronizer
(
    input clk_a,
    input clk_b,
    input arstn,
    input brstn,
    input [3:0] data_in,
    input data_en,
    output reg [3:0] dataout
);

reg [3:0] data_reg;
reg [3:0] en_data_reg;
reg en_clap_one;
reg en_clap_two;

always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        data_reg <= 4'b0;
    end else begin
        data_reg <= data_in;
    end
end

always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        en_data_reg <= 4'b0;
    end else begin
        en_data_reg <= data_en;
    end
end

always @(posedge clk_b or negedge brstn) begin
    if (!brstn) begin
        en_clap_one <= 1'b0;
        en_clap_two <= 1'b0;
    end else begin
        en_clap_one <= en_data_reg;
        en_clap_two <= en_clap_one;
    end
end

always @(posedge clk_b or negedge brstn) begin
    if (!brstn) begin
        dataout <= 4'b0;
    end else begin
        if (en_clap_two) begin
            dataout <= data_reg;
        end else begin
            dataout <= dataout;
        end
    end
end
endmodule

module multi_pipe_8bit
(
    input clk,
    input rst_n,
    input mul_en_in,
    input mul_a,
    input mul_b,
    output mul_en_out,
    output mul_out
);

reg [3:0] mul_en_out_reg;
reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
reg [15:0] temp [7:0];
reg [15:0] sum [3:0];
reg [15:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_en_out_reg <= 4'b0;
    end else begin
        mul_en_out_reg <= {mul_en_out_reg[2:0], mul_en_in};
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
    end else if (mul_en_in) begin
        mul_a_reg <= mul_a;
        mul_b_reg <= mul_b;
    end
end

assign temp[0] = mul_b_reg[0] ? {{8{mul_a_reg[7]}}, mul_a_reg} : 16'b0;
assign temp[1] = mul_b_reg[1] ? {{7{mul_a_reg[7]}}, mul_a_reg, 1'b0} : 16'b0;
assign temp[2] = mul_b_reg[2] ? {{6{mul_a_reg[7]}}, mul_a_reg, 2'b0} : 16'b0;
assign temp[3] = mul_b_reg[3] ? {{5{mul_a_reg[7]}}, mul_a_reg, 3'b0} : 16'b0;
assign temp[4] = mul_b_reg[4] ? {{4{mul_a_reg[7]}}, mul_a_reg, 4'b0} : 16'b0;
assign temp[5] = mul_b_reg[5] ? {{3{mul_a_reg[7]}}, mul_a_reg, 5'b0} : 16'b0;
assign temp[6] = mul_b_reg[6] ? {{2{mul_a_reg[7]}}, mul_a_reg, 6'b0} : 16'b0;
assign temp[7] = mul_b_reg[7] ? {{1{mul_a_reg[7]}}, mul_a_reg, 7'b0} : 16'b0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum[0] <= 16'b0;
        sum[1] <= 16'b0;
        sum[2] <= 16'b0;
        sum[3] <= 16'b0;
    end else begin
        sum[0] <= temp[0] + temp[1];
        sum[1] <= temp[2] + temp[3];
        sum[2] <= temp[4] + temp[5];
        sum[3] <= temp[6] + temp[7];
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out_reg <= 16'b0;
    end else begin
        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
    end
end

assign mul_out = mul_en_out_reg[3] ? mul_out_reg : 16'b0;
endmodule

module right_shifter
(
    input clk,
    input d,
    output reg q
);

always @(posedge clk) begin
    q <= (q >> 1) | {7'b0, d};
end

