module div_8bit
(
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    input res_ready,
    output reg res_valid,
    output [15:0] result
);

    reg [15:0] sr;
    reg [7:0] neg_divisor;
    reg [3:0] cnt;
    reg start_cnt;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            res_valid <= 1'b0;
        end else if (cnt == 4'd8 && start_cnt == 1'b1) begin
            cnt <= 4'd0;
            start_cnt <= 1'b0;
            sr[15:8] <= sr[15:8];
            sr[7:0] <= sr[7:0];
        end else if (start_cnt == 1'b1) begin
            sr <= sr - {neg_divisor, 8'b0};
            cnt <= cnt + 1;
        end else if (res_valid == 1'b1 && res_ready == 1'b1) begin
            res_valid <= 1'b0;
        end else begin
            res_valid <= res_valid;
        end
    end

    assign result = {sr[15:8], sr[7:0]};
endmodule

module pulse_detect
(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

parameter s0 = 2'b00;
parameter s1 = 2'b01;
parameter s2 = 2'b10;
parameter s3 = 2'b11;

reg [1:0] state;
reg [1:0] next_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= s0;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        s0: begin
            if (data_in == 1'b0) begin
                next_state = s1;
            end else begin
                next_state = s0;
            end
        end

        s1: begin
            if (data_in == 1'b1) begin
                next_state = s2;
            end else begin
                next_state = s1;
            end
        end

        s2: begin
            if (data_in == 1'b0) begin
                next_state = s3;
            end else begin
                next_state = s0;
            end
        end

        s3: begin
            if (data_in == 1'b1) begin
                next_state = s2;
            end else begin
                next_state = s1;
            end
        end

        default: begin
            next_state = s0;
        end
    endcase
end

always @(*) begin
    case (state)
        s2: begin
            if (data_in == 1'b0) begin
                data_out = 1'b1;
            end else begin
                data_out = 1'b0;
            end
        end

        default: begin
            data_out = 1'b0;
        end
    endcase
end
endmodule

module multi_pipe_4bit
#(
    parameter size = 4
)
(
