    input rst_n,
    input mul_a,
    input mul_b,
    output reg mul_out
);

reg [size-1:0] mul_a_reg;
reg [size-1:0] mul_b_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 0;
        mul_b_reg <= 0;
        mul_out <= 0;
    end else begin
        mul_a_reg <= mul_a;
        mul_b_reg <= mul_b;
        mul_out <= mul_a_reg * mul_b_reg;
    end
end

endmodule

module traffic_light
(
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red
);

localparam IDLE = 2'b00;
localparam S1_RED = 2'b01;
localparam S2_YELLOW = 2'b10;
localparam S3_GREEN = 2'b11;

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        cnt <= 0;
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        case (state)
            IDLE: begin
                state <= S1_RED;
                cnt <= 60;
            end
            S1_RED: begin
                if (cnt == 3) begin
                    state <= S3_GREEN;
                    cnt <= 10;
                end else begin
                    cnt <= cnt - 1;
                end
                p_red <= 1;
                p_yellow <= 0;
                p_green <= 0;
            end
            S2_YELLOW: begin
                if (cnt == 3) begin
                    state <= S1_RED;
                    cnt <= 5;
                end else begin
                    cnt <= cnt - 1;
                end
                p_red <= 0;
                p_yellow <= 1;
                p_green <= 0;
            end
            S3_GREEN: begin
                if (cnt == 3) begin
                    state <= S2_YELLOW;
                    cnt <= 10;
                end else begin
                    cnt <= cnt - 1;
                end
                p_red <= 0;
                p_yellow <= 0;
                p_green <= 1;
            end
        endcase
    end
end

always @(*) begin
    if (pass_request && green && (cnt > 10)) begin
        cnt = 10;
    end
end

assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;
assign clock = cnt;

endmodule

module alu
(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [31:0] res;
wire [31:0] a_signed, b_signed;
assign a_signed = {a[31], a};
assign b_signed = {b[31], b};

always @(*) begin
    case (aluc)
        ADD: res = a + b;
        ADDU: res = a + b;
        SUB: res = a - b;
        SUBU: res = a - b;
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: res = a_signed < b_signed ? 32'hFFFFFFFF : 32'h00000000;
        SLTU: res = a < b ? 32'hFFFFFFFF : 32'h00000000;
        SLL: res = a << b[5:0];
        SRL: res = a >> b[5:0];
        SRA: res = $signed(a) >>> b[5:0];
        SLLV: res = a << b[5:0];
        SRLV: res = a >> b[5:0];
        SRAV: res = $signed(a) >>> b[5:0];
        LUI: res = {b, 16'h0000};
        default: res = 32'h00000000;
    endcase
end

assign r = res;
assign zero = (res == 32'h00000000) ? 1'b1 : 1'b0;
assign carry = (aluc == ADD || aluc == ADDU) ? (res[31] != res[30]) : 1'b0;
assign negative = res[31];
assign overflow = (aluc == ADD || aluc == SUB) ? ((a[31] == b[31]) != res[31]) : 1'b0;
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'b0;

endmodule
